"""Export curated coding decisions. This does not code legal texts automatically."""
from pathlib import Path
import csv,json,html,urllib.parse
ROOT=Path(__file__).resolve().parents[1]
DATA=ROOT/'data/statute_coding'
P=json.loads((DATA/'pilot_decisions.json').read_text())
def export(name,items):
 with (DATA/name).open('w',encoding='utf-8',newline='') as f:
  w=csv.DictWriter(f,fieldnames=list(items[0]),lineterminator='\n');w.writeheader();w.writerows(items)
for name,key in [('codebook_v0_1.csv','codebook'),('pilot_coding.csv','coding'),('pilot_evidence.csv','evidence')]:export(name,P[key])
if 'documents' in P:export('pilot_documents.csv',P['documents'])
sources={x['document_id']:x for x in csv.DictReader((DATA/'pilot_documents.csv').open())}
evidence={}
for e in P['evidence']:evidence.setdefault(e['row_id'],[]).append(e)
esc=lambda x:html.escape(str(x))
sections=[]
for r in P['coding']:
 excerpts=[]
 for e in evidence[r['row_id']]:
  d=sources[e['document_id']];href='../../'+urllib.parse.quote(d['source_file'])+'#page='+str(e['pdf_page'])
  excerpts.append(f'<div class="evidence"><a href="{href}" target="_blank">{esc(e["document_id"])} · PDF p. {e["pdf_page"]} · {esc(e["article"])}</a><small>{esc(e["evidence_role"].replace("_"," "))} · {esc(d["instrument_type"].replace("_"," "))}</small><blockquote lang="es">{esc(e["excerpt_es"])}</blockquote></div>')
 attrs=' '.join(f'data-{k}="{esc(r[k])}"' for k in ['case_id','dimension','provision_status'])
 search=esc(' '.join(str(v) for v in r.values()))
 sections.append(f'''<article {attrs} data-search="{search}"><div class="rowhead"><span>{esc(r['case_id'])} / {esc(r['indicator_id'])}</span><span class="badge {r['provision_status']}">{esc(r['provision_status'].replace('_',' '))}</span></div><h3>{esc(r['indicator'])}</h3><p>{esc(r['summary_en'])}</p><p class="notes"><strong>Exceptions and limits:</strong> {esc(r['exceptions_and_limits'])}</p><details><summary>Spanish evidence and source pages ({len(excerpts)})</summary>{''.join(excerpts)}</details><div class="meta">Code: {esc(r['coded_value'])} · Interpretation confidence: {r['text_interpretation_confidence']} · Team review pending · Current legal force unverified</div></article>''')
case_names={'PBA_PRI':'Buenos Aires · Primary','MIS_PRI':'Misiones · Primary','COR_PRI':'Córdoba · Primary','COR_SEC':'Córdoba · Secondary extension'}
opts=lambda key:''.join(f'<option value="{esc(x)}">{esc(case_names.get(x,x.replace("_"," ")))}</option>' for x in sorted(set(r[key] for r in P['coding'])))
book=''.join(f'<tr><td>{esc(c["indicator_id"])}</td><td>{esc(c["indicator"])}</td><td>{esc(c["decision_rule"])}</td></tr>' for c in P['codebook'])
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Statute coding pilot review</title><style>
*{box-sizing:border-box}body{margin:0;background:#f6f5f1;color:#172c40;font:16px/1.6 Arial,sans-serif}main{max-width:1100px;margin:auto;padding:40px 24px}h1,h2{font-family:Georgia,serif;font-weight:normal;line-height:1.15}h1{font-size:44px;margin:10px 0 20px}h2{font-size:30px}h3{font-size:19px;margin:12px 0}.eyebrow{font-size:11px;letter-spacing:2px;color:#145bc4;font-weight:bold}.intro{font-size:18px;max-width:830px}.notice{background:#fff0cf;border-left:4px solid #ba8c24;padding:15px 20px;margin:20px 0;font-size:14px}.links{display:flex;gap:18px;flex-wrap:wrap;font-size:13px}a{color:#1359b5}.controls{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;padding:20px;background:#e6edf6;margin-top:30px}.controls label{display:block;font-size:12px;font-weight:bold}.controls select,.controls input{width:100%;padding:10px;background:white;border:1px solid #b2c0cf;font:inherit;color:#172c40}.search{grid-column:1/-1}article{background:white;border:1px solid #cfd8e1;margin:18px 0;padding:24px}.rowhead{display:flex;justify-content:space-between;gap:15px;font-size:12px;letter-spacing:.3px;font-weight:bold}.badge{padding:2px 9px;border-radius:3px;background:#e6f2ed;color:#116448}.badge.unclear{background:#fff0cf;color:#705400}.badge.not_found{background:#edf0f4;color:#4c5c6f}.notes{font-size:14px;color:#526477}.meta{border-top:1px solid #e0e5eb;padding-top:12px;margin-top:16px;font-size:11px;color:#607183;overflow-wrap:anywhere}summary{cursor:pointer;font-size:14px;font-weight:bold}.evidence{padding:15px 0;border-bottom:1px solid #e1e6ec}.evidence small{display:block;color:#697988;font-size:11px}blockquote{margin:8px 0;padding:8px 16px;background:#f3f6fa;font-family:Georgia,serif;font-size:16px;border-left:3px solid #7b9cc6}table{width:100%;border-collapse:collapse;font-size:13px}td,th{border:1px solid #cad3dc;padding:10px;text-align:left;vertical-align:top}.count{font-size:14px;color:#526477}[hidden]{display:none!important}button{font:inherit;padding:7px 14px;cursor:pointer;border:1px solid #95aac3;background:white;color:#172c40}select:focus-visible,input:focus-visible,button:focus-visible,a:focus-visible{outline:3px solid #236dd4;outline-offset:3px}.tablewrap{overflow-x:auto}@media(max-width:650px){.controls{grid-template-columns:1fr}.search{grid-column:auto}h1{font-size:34px}article{padding:18px}.rowhead{font-size:10px}}@media print{.controls,.links{display:none}article{break-inside:avoid}details{display:block}body{background:white}}</style></head><body><main><div class="eyebrow">ARGENTINA / MODEL TEACHER STATUTE / PILOT 0.1.0</div><h1>What do the supplied statutes prescribe?</h1><p class="intro">A first coding pass for Buenos Aires, Misiones and Córdoba. The common comparison is primary education; Córdoba secondary is kept as a separate extension.</p><div class="notice"><strong>Draft for team review.</strong> 16 indicators · 64 coding decisions · 124 Spanish excerpts · 7 PDFs. These are formal provisions from documents supplied for the assignment. Current legal force and implementation are not verified. “Not found” does not mean a policy does not exist.</div><div class="links"><a href="pilot_findings.md">Read the initial comparison</a><a href="README.md">Coding protocol</a><a href="../../data/statute_coding/pilot_coding.csv">Coding table (CSV)</a><a href="../../data/statute_coding/pilot_evidence.csv">Evidence table (CSV)</a><a href="../../data/statute_coding/review_queue.csv">Review queue (CSV)</a></div><div class="controls"><div><label for="case">Comparison case</label><select id="case"><option value="">All four cases</option>CASE_OPTIONS</select></div><div><label for="dimension">Dimension</label><select id="dimension"><option value="">All four dimensions</option>DIM_OPTIONS</select></div><div><label for="status">Provision status</label><select id="status"><option value="">All statuses</option>STATUS_OPTIONS</select></div><div class="search"><label for="search">Search findings, codes or article notes</label><input id="search" type="search" placeholder="e.g. appraisal, seniority, substitute, Law 10237"></div></div><p class="count" id="count" aria-live="polite"></p><button id="reset">Reset filters</button><section id="rows">ROWS</section><h2>Codebook at a glance</h2><p>Codes describe mechanisms, not policy quality. See the CSV codebook and protocol for permitted values and status definitions.</p><div class="tablewrap"><table><thead><tr><th>Code</th><th>Indicator</th><th>Decision rule</th></tr></thead><tbody>BOOK</tbody></table></div><p class="count">PDF links open local source files; data and evidence remain on your computer. No source PDFs are embedded in this document.</p></main><script>
const ids=['case','dimension','status','search'];function filter(){const c=document.getElementById('case').value,d=document.getElementById('dimension').value,s=document.getElementById('status').value,q=document.getElementById('search').value.toLocaleLowerCase();let n=0;document.querySelectorAll('#rows article').forEach(r=>{r.hidden=!!((c&&r.dataset.case_id!==c)||(d&&r.dataset.dimension!==d)||(s&&r.dataset.provision_status!==s)||(q&&!r.dataset.search.toLocaleLowerCase().includes(q)));if(!r.hidden)n++});document.getElementById('count').textContent=n+' of 64 coding decisions shown.'}ids.forEach(id=>document.getElementById(id).addEventListener('input',filter));document.getElementById('reset').onclick=()=>{ids.forEach(id=>document.getElementById(id).value='');filter()};filter();</script></body></html>'''
page=page.replace('124 Spanish excerpts',str(len(P['evidence']))+' Spanish excerpts')
page=page.replace('CASE_OPTIONS',opts('case_id')).replace('DIM_OPTIONS',opts('dimension')).replace('STATUS_OPTIONS',opts('provision_status')).replace('ROWS',''.join(sections)).replace('BOOK',book)
(ROOT/'docs/statute_coding/pilot_review.html').write_text(page,encoding='utf-8')
print('Exported pilot tables and local review document.')
